// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Все баннеры со статусом и числом закрывших
	// (GET /admin/banners)
	ListAdminBanners(ctx context.Context, request ListAdminBannersRequestObject) (ListAdminBannersResponseObject, error)
	// Создать баннер
	// (POST /admin/banners)
	CreateBanner(ctx context.Context, request CreateBannerRequestObject) (CreateBannerResponseObject, error)
	// Снять баннер сейчас
	// (POST /admin/banners/{banner_id}/end)
	EndBanner(ctx context.Context, request EndBannerRequestObject) (EndBannerResponseObject, error)
	// Баннеры администратора, которые сейчас видит студент (D61)
	// (GET /me/banners)
	GetMyBanners(ctx context.Context, request GetMyBannersRequestObject) (GetMyBannersResponseObject, error)
	// Скрыть обычный баннер
	// (POST /me/banners/{banner_id}/dismiss)
	DismissBanner(ctx context.Context, request DismissBannerRequestObject) (DismissBannerResponseObject, error)
	// Ближайшие дедлайны (F5, напоминания)
	// (GET /me/deadlines)
	GetMyDeadlines(ctx context.Context, request GetMyDeadlinesRequestObject) (GetMyDeadlinesResponseObject, error)
	// Лента уведомлений (F5)
	// (GET /me/feed)
	GetMyFeed(ctx context.Context, request GetMyFeedRequestObject) (GetMyFeedResponseObject, error)
	// Счётчики для значка в шапке и главной «Сегодня»
	// (GET /me/feed/counters)
	GetMyFeedCounters(ctx context.Context, request GetMyFeedCountersRequestObject) (GetMyFeedCountersResponseObject, error)
	// Отметить всё прочитанным
	// (POST /me/feed/read-all)
	MarkAllFeedRead(ctx context.Context, request MarkAllFeedReadRequestObject) (MarkAllFeedReadResponseObject, error)
	// Подтвердить ознакомление с важным объявлением (I3)
	// (POST /me/feed/{item_id}/ack)
	AckFeedItem(ctx context.Context, request AckFeedItemRequestObject) (AckFeedItemResponseObject, error)
	// Отменить «Пойду»
	// (DELETE /me/feed/{item_id}/going)
	UnmarkFeedItemGoing(ctx context.Context, request UnmarkFeedItemGoingRequestObject) (UnmarkFeedItemGoingResponseObject, error)
	// «Пойду» на мероприятие (D61)
	// (POST /me/feed/{item_id}/going)
	MarkFeedItemGoing(ctx context.Context, request MarkFeedItemGoingRequestObject) (MarkFeedItemGoingResponseObject, error)
	// Отметить прочитанным
	// (POST /me/feed/{item_id}/read)
	MarkFeedItemRead(ctx context.Context, request MarkFeedItemReadRequestObject) (MarkFeedItemReadResponseObject, error)
	// Объявления и новости, созданные деканатом
	// (GET /staff/announcements)
	ListStaffAnnouncements(ctx context.Context, request ListStaffAnnouncementsRequestObject) (ListStaffAnnouncementsResponseObject, error)
	// Опубликовать новость или объявление
	// (POST /staff/announcements)
	CreateAnnouncement(ctx context.Context, request CreateAnnouncementRequestObject) (CreateAnnouncementResponseObject, error)
	// Кто ознакомился с объявлением (I3)
	// (GET /staff/announcements/{announcement_id}/acks)
	GetAnnouncementAcks(ctx context.Context, request GetAnnouncementAcksRequestObject) (GetAnnouncementAcksResponseObject, error)
	// Дедлайны, созданные деканатом
	// (GET /staff/deadlines)
	ListStaffDeadlines(ctx context.Context, request ListStaffDeadlinesRequestObject) (ListStaffDeadlinesResponseObject, error)
	// Создать дедлайн
	// (POST /staff/deadlines)
	CreateDeadline(ctx context.Context, request CreateDeadlineRequestObject) (CreateDeadlineResponseObject, error)
	// Удалить дедлайн
	// (DELETE /staff/deadlines/{deadline_id})
	DeleteDeadline(ctx context.Context, request DeleteDeadlineRequestObject) (DeleteDeadlineResponseObject, error)
}

type StrictHandlerFunc = strictnethttp.StrictHTTPHandlerFunc
type StrictMiddlewareFunc = strictnethttp.StrictHTTPMiddlewareFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

